// GENERATED by scripts/make-dashboard-function.cjs from connect-account-status/index.ts and _shared/rateLimit.ts,
// so it can be pasted into the dashboard as ONE file with no other files. Do not edit it by
// hand; edit the real files and run the script again.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ---- inlined from _shared/rateLimit.ts ----
interface RateLimitConfig {
  windowSeconds: number;
  maxRequests: number;
}

// Prefer the authenticated user's id when available (tighter, can't be
// evaded by rotating IPs); fall back to IP for endpoints with no reliable
// caller identity.
function clientIdentifier(req: Request, userId?: string | null): string {
  if (userId) return `user:${userId}`;
  const forwarded = req.headers.get("x-forwarded-for");
  const ip = forwarded ? forwarded.split(",")[0].trim() : "unknown";
  return `ip:${ip}`;
}

async function checkRateLimit(
  supabaseAdmin: ReturnType<typeof createClient>,
  bucket: string,
  identifier: string,
  config: RateLimitConfig
): Promise<boolean> {
  const { data, error } = await supabaseAdmin.rpc("check_rate_limit", {
    p_bucket_key: `${bucket}:${identifier}`,
    p_window_seconds: config.windowSeconds,
    p_max_requests: config.maxRequests,
  });

  // Fail open on infra errors - a broken rate limiter shouldn't take every
  // endpoint in the app down with it.
  if (error) {
    console.error(`Rate limit check failed for ${bucket}:`, error);
    return true;
  }

  return data === true;
}

function rateLimitResponse(corsHeaders: Record<string, string>): Response {
  return new Response(JSON.stringify({ error: "Too many requests. Please try again shortly." }), {
    status: 429,
    headers: { ...corsHeaders, "Content-Type": "application/json", "Retry-After": "60" },
  });
}
// ---- end of rateLimit ----

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const authHeader = req.headers.get("Authorization") ?? "";
    const callerClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY") ?? "", {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user: caller }, error: callerError } = await callerClient.auth.getUser();
    if (callerError || !caller) {
      return new Response(JSON.stringify({ error: "Not authorized" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseAdmin = createClient(supabaseUrl, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "");

    const withinLimit = await checkRateLimit(supabaseAdmin, "connect-account-status", clientIdentifier(req, caller.id), {
      windowSeconds: 60,
      maxRequests: 30,
    });
    if (!withinLimit) return rateLimitResponse(corsHeaders);

    const { creator_id } = await req.json().catch(() => ({ creator_id: undefined }));

    // Checking someone ELSE's status (used by the brand's pay-flow soft
    // warning) only ever returns the one non-sensitive boolean it needs -
    // never the account id or other detail, and never hits Stripe (reads
    // the cached flag, refreshed whenever that creator visits their own
    // Payouts screen).
    if (creator_id && creator_id !== caller.id) {
      const { data } = await supabaseAdmin
        .from("creator_stripe_accounts")
        .select("payouts_enabled")
        .eq("user_id", creator_id)
        .maybeSingle();
      return new Response(JSON.stringify({ payouts_enabled: !!data?.payouts_enabled }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: account } = await supabaseAdmin
      .from("creator_stripe_accounts")
      .select("stripe_account_id")
      .eq("user_id", caller.id)
      .maybeSingle();

    if (!account) {
      return new Response(JSON.stringify({ connected: false }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const stripeRes = await fetch(`https://api.stripe.com/v1/accounts/${account.stripe_account_id}`, {
      headers: { "Authorization": `Bearer ${Deno.env.get("STRIPE_SECRET_KEY")}` },
    });
    const stripeAccount = await stripeRes.json();
    if (!stripeAccount.id) throw new Error("Failed to read Stripe account: " + JSON.stringify(stripeAccount));

    const flags = {
      charges_enabled: !!stripeAccount.charges_enabled,
      payouts_enabled: !!stripeAccount.payouts_enabled,
      details_submitted: !!stripeAccount.details_submitted,
    };

    await supabaseAdmin.from("creator_stripe_accounts").update({
      ...flags,
      updated_at: new Date().toISOString(),
    }).eq("user_id", caller.id);

    return new Response(JSON.stringify({ connected: true, ...flags }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    console.error("connect-account-status error:", err);
    return new Response(JSON.stringify({ error: String((err as Error).message || err) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
